const items = $input.all();
return items.map(item => {
  const data = item.json.body || item.json;
  let pan = (data.pan || "").toString().trim().toUpperCase();

  // Extract from GSTIN if pan not directly provided (chars 3 to 12 of GSTIN)
  if (!pan && data.gstin && data.gstin.length === 15) {
    pan = data.gstin.substring(2, 12);
  }
  if (!pan) {
    pan = "AABCU9603R";
  }

  const bidder_name = (data.bidder_name || "ABC Technologies Pvt Ltd").toString().trim();
  return {
    json: {
      request_id: data.request_id || "REQ-PAN-DEMO",
      bidder_name,
      pan,
      agent: "PAN_AGENT",
      raw_input: data
    }
  };
});

const items = $input.all();
const MOCK_PAN_REGISTRY = {
  "AABCU9603R": {
    registered_name: "ABC Technologies Pvt Ltd",
    pan_type: "Company",
    status: "VALID_AND_OPERATIVE",
    aadhaar_seeding_status: "NOT_APPLICABLE_COMPANY",
    category: "C - Company",
    issuance_date: "2015-04-12"
  },
  "AAACB1234P": {
    registered_name: "Mismatch Enterprises Ltd",
    pan_type: "Individual",
    status: "VALID_AND_OPERATIVE",
    aadhaar_seeding_status: "SEEDED",
    category: "P - Person",
    issuance_date: "2018-09-20"
  },
  "AABCS1234D": {
    registered_name: "Cancelled Vendor Pvt Ltd",
    pan_type: "Company",
    status: "INOPERATIVE_DEACTIVATED",
    aadhaar_seeding_status: "NOT_SEEDED_INOPERATIVE",
    category: "C - Company",
    issuance_date: "2016-11-05"
  }
};

let rawInput = {};
try {
  rawInput = $('🔍 Input Validation').first().json || {};
} catch (e) {
  rawInput = {};
}

return items.map(item => {
  const data = item.json;
  let pan = (data.pan || (data.evidence && data.evidence.pan) || rawInput.pan || (rawInput.raw_input && rawInput.raw_input.pan) || "").toString().toUpperCase().trim();
  if (!pan && rawInput.gstin && rawInput.gstin.length === 15) {
    pan = rawInput.gstin.substring(2, 12);
  }
  const bidderName = (data.bidder_name || rawInput.bidder_name || (rawInput.raw_input && rawInput.raw_input.bidder_name) || "ABC Technologies Pvt Ltd").toString().trim();
  const registryEntry = MOCK_PAN_REGISTRY[pan] || null;

  return {
    json: {
      ...data,
      bidder_name: bidderName,
      pan,
      mock_record_found: !!registryEntry,
      mock_pan_record: registryEntry
    }
  };
});

const items = $input.all();
const PAN_REGEX = /^[A-Z]{5}[0-9]{4}[A-Z]{1}$/;
const ENTITY_MAP = {
  'C': 'Company',
  'P': 'Individual/Person',
  'H': 'Hindu Undivided Family (HUF)',
  'F': 'Partnership Firm / LLP',
  'A': 'Association of Persons (AOP)',
  'T': 'Trust',
  'B': 'Body of Individuals (BOI)',
  'L': 'Local Authority',
  'J': 'Artificial Juridical Person',
  'G': 'Government Agency'
};

return items.map(item => {
  const data = item.json;
  const pan = data.pan || "";
  const formatValid = PAN_REGEX.test(pan);

  let entityType = "Unknown";
  let entityCode = null;
  if (formatValid) {
    entityCode = pan[3];
    entityType = ENTITY_MAP[entityCode] || "Other Entity";
  }

  return {
    json: {
      ...data,
      format_valid: formatValid,
      entity_code: entityCode,
      entity_type_desc: entityType
    }
  };
});

const items = $input.all();
return items.map(item => {
  const data = item.json;
  const bidderName = (data.bidder_name || "").toUpperCase().trim();
  const record = data.mock_pan_record;
  const issues = [];
  let status = "VERIFIED";
  let confidence = 0.98;
  let riskLevel = "LOW";

  if (!data.format_valid) {
    status = "NOT_VERIFIED";
    confidence = 0.95;
    riskLevel = "HIGH";
    issues.push(`PAN format invalid: '${data.pan}' does not comply with 10-character statutory format (AAAAA9999A)`);
  } else if (!data.mock_record_found) {
    status = "NOT_VERIFIED";
    confidence = 0.90;
    riskLevel = "HIGH";
    issues.push(`PAN '${data.pan}' not found in mock CBDT/NSDL registry`);
  } else if (record.status !== "VALID_AND_OPERATIVE") {
    status = "NOT_VERIFIED";
    confidence = 0.96;
    riskLevel = "HIGH";
    issues.push(`PAN status is '${record.status}' for registered taxpayer ${record.registered_name}`);
  } else {
    const regName = record.registered_name.toUpperCase().trim();
    const exactMatch = bidderName === regName;
    const partialMatch = bidderName.includes(regName) || regName.includes(bidderName);

    if (!exactMatch && !partialMatch) {
      status = "REVIEW";
      confidence = 0.60;
      riskLevel = "MEDIUM";
      issues.push(`Name consistency mismatch: Bidder name '${data.bidder_name}' differs from PAN registered entity '${record.registered_name}'`);
    } else {
      status = "VERIFIED";
      confidence = 0.98;
      riskLevel = "LOW";
    }
  }

  return {
    json: {
      ...data,
      name_check_status: status,
      name_check_confidence: confidence,
      name_check_risk: riskLevel,
      name_check_issues: issues
    }
  };
});

const items = $input.all();
return items.map(item => {
  const data = item.json;
  const record = data.mock_pan_record;

  return {
    json: {
      agent: "PAN_AGENT",
      status: data.name_check_status,
      confidence: data.name_check_confidence,
      evidence: {
        pan: data.pan,
        registered_name: record ? record.registered_name : null,
        pan_type: record ? record.pan_type : data.entity_type_desc,
        status: record ? record.status : "UNREGISTERED",
        category: record ? record.category : null,
        issuance_date: record ? record.issuance_date : null,
        aadhaar_seeding_status: record ? record.aadhaar_seeding_status : null,
        registry_source: "MOCK_CBDT_NSDL_PORTAL"
      },
      issues: data.name_check_issues || [],
      risk_level: data.name_check_risk,
      timestamp: new Date().toISOString()
    }
  };
});

const items = $input.all();
return items.map(item => ({
  json: {
    agent: "PAN_AGENT",
    status: "REVIEW",
    confidence: 0.0,
    evidence: {
      error: "PAN verification agent encountered an execution failure",
      fallback_mode: true
    },
    issues: ["PAN verification agent failed"],
    risk_level: "MEDIUM",
    timestamp: new Date().toISOString()
  }
}));
